first.patch:
goal = find(category="zone", color="green")
while True:
  todo = [(o, goal) for o in find_all(category="carton") if not on_top(o, goal)]
  if not todo:
    break
  p = max(todo, key=lambda p: (p[0].x - p[1].x) * (p[0].x - p[1].x) + (p[0].y - p[1].y) * (p[0].y - p[1].y))
  if not p[0].attached:
    pick(p[0])
  place(p[0], p[1])
verify(lambda: all(on_top(o, goal) for o in find_all(category="carton")), "a carton is not on the zone")

